@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

	push("最近",	`/api/nq/amp_last_serial_novel_updates?page={{page}}&limit=50&language=cn`, 0, 0.29);

fl=[["连载","lianzai"],["随选","suixuan"],["玄幻","xuanhuan"],["都市","dushi"],
["仙侠","xianxia"],["言情","gudaiyanqing"],
["穿越","chuanyuechongsheng"],["游戏","youxi"],["科幻","kehuan"],["悬疑","xuanyi"],["灵异","lingyi"],["历史","lishi"],["青春","qingchun"],["军事","junshi"],["竞技","jingji"],["现言","yanqing"],["其他","qita"]
];
java.put("fl",fl);
fl.map(([title,id],index)=>{

	url= `/api/nq/amp_novel_list?type=${id}&filter=*&page={{page}}&limit=18&language=cn`;
	if(index+1 <= fl.length - fl.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}

    })

JSON.stringify(sort);

